
/* 협동 보스전 소식 줄: 친구·보스가 뭘 했는지 한 줄씩 보여 줘요. 누르면 최근 기록을 펼쳐요 */
(function(){
 const MAXH=30,SHOW_MS=4500,OPEN_MS=9000;
 let hist=[],owner=null,box=null,tmr=0,open=false;
 const esc2=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
 function ensureBox(){if(box)return box;box=document.createElement('div');box.id='bLog';box.addEventListener('click',()=>{open=!open;render(true);});document.body.appendChild(box);return box;}
 function render(force){
  const b=ensureBox();
  if(!(B&&B.coop&&S.screen==='battle')){hist=[];open=false;b.classList.remove('on');return;}
  if(!hist.length){b.classList.remove('on');return;}
  const n=open?6:1,rows=hist.slice(-n);
  b.innerHTML=rows.map((e,i)=>`<div class="bl ${e.a==='b'?'b':''} ${open&&i<rows.length-1?'old':''}"><b>${e.a==='b'?'👾':'👤'} ${esc2(e.n)}</b><span class=tx>${e.x}</span></div>`).join('')+(open?'<div class=hint>눌러서 접기</div>':'');
  b.classList.add('on');
  clearTimeout(tmr);tmr=setTimeout(()=>{if(open){open=false;render();}else b.classList.remove('on');},open?OPEN_MS:SHOW_MS);
 }
 /* 화면에 보여 줄 소식(내가 한 행동은 빼요): a = 0 방장, 1 친구, 'b' 보스 */
 window.bossLogShow=function(e){
  try{if(!e||!B||!B.coop)return;
   if(e.a!=='b'&&Number(e.a)===BC.localIndex)return;
   hist.push({a:e.a,n:e.n,x:e.x});if(hist.length>MAXH)hist.shift();
   render();}catch(err){}};
 /* 방장이 소식을 만들어 두 화면에 보내요 */
 window.bossLog=function(a,txt){
  try{if(!BC.host||!B||!B.coop||window.__sim)return;
   const nm=a==='b'?'보스':((B.coop.players[a]||{}).name||'친구');
   const e={a,n:nm,x:txt};
   bossLogShow(e);
   if(BC.conn&&BC.conn.open)bossSend({t:'boss-log',a,n:nm,x:txt});}catch(err){}};
 const idx=P=>{try{return B.coop.players.indexOf(P);}catch(e){return -1;}};
 const cardName=c=>c==null?'카드':(typeof c==='object'?(c.name||c.item||'아이템'):(MON[c]?MON[c].name:'카드'));
 const foeHP=()=>B.foe.board.reduce((s,u)=>s+(u&&u.hp>0?u.hp:0),0);
 const ourHP=()=>{const ps=B.coop.players,bd=(B.me&&B.me.board)||[];return ps.reduce((s,p)=>s+Math.max(0,p.hp||0),0)+bd.reduce((s,u)=>s+(u&&u.hp>0?u.hp:0),0);};
 function wrap(name,pre){const f=window[name];if(typeof f!=='function')return;
  window[name]=function(...a){let post=null;
   try{if(BC.host&&B&&B.coop&&!B.coop.result&&!window.__sim)post=pre.apply(this,a);}catch(e){post=null;}
   const r=f.apply(this,a);
   if(post){const fin=v=>{try{post(v);}catch(e){}return v;};return r&&typeof r.then==='function'?r.then(fin):fin(r);}
   return r;};}
 wrap('summon',(P,h)=>{const i=idx(P),c=P.hand[h];if(i<0)return null;const nm=cardName(c);return()=>bossLog(i,`소환 → ${esc2(nm)}`);});
 wrap('playItem',(P,h)=>{const i=idx(P),c=P.hand[h];if(i<0||!c)return null;const nm=cardName(c);return v=>{if(v!==false)bossLog(i,`아이템 → ${esc2(nm)}`);};});
 wrap('megaDo',(P,si)=>{const i=idx(P),u=P&&P.board[si];if(i<0||!u)return null;const nm=cardName(u.id);return v=>{if(v!==false)bossLog(i,`메가진화 → ${esc2(nm)}`);};});
 wrap('gmaxDo',(P,si)=>{const i=idx(P),u=P&&P.board[si];if(i<0||!u)return null;const nm=cardName(u.id);return v=>{if(v!==false)bossLog(i,`거다이맥스 → ${esc2(nm)}`);};});
 wrap('playerAttack',(si,tg,ok,crit)=>{const P=B.me,i=idx(P),u=P.board[si];if(i<0||!u)return null;const nm=cardName(u.id),before=foeHP();return()=>{const d=before-foeHP();bossLog(i,`${esc2(nm)} 공격${ok?'':'(오답)'} → 보스 -${Math.max(0,d)}${ok&&crit?' 크리티컬!':''}`);};});
 wrap('bossApplyPower',(ok)=>{const i=idx(B.me);if(i<0)return null;return()=>bossLog(i,ok?'공부 기술 성공 → 카드 +1':'공부 기술 실패');});
 wrap('endTurn',()=>{bossLog(B.coop.active,'차례 종료');return null;});
 wrap('resolveAttack',(A,D,si,tg)=>{if(A!==B.foe)return null;const u=A.board[si];if(!u)return null;const nm=cardName(u.id),before=ourHP(),hero=!!(tg&&tg.hero);return()=>{const d=before-ourHP();bossLog('b',`${esc2(nm)} 공격 → ${hero?'트레이너':'아군'} -${Math.max(0,d)}`);};});
 setInterval(()=>{try{if(!(B&&B.coop&&S.screen==='battle')&&(hist.length||(box&&box.classList.contains('on')))){hist=[];open=false;if(box)box.classList.remove('on');}}catch(e){}},1000);
})();

/* ===== 이야기 인물 일러스트 (도트 느낌 45장) ===== */
const CHAR_ART2=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
CHAR_ART2.push('data:image/webp;base64,'); // [45] 라온(은빛 머리)
const CHAR_ART={hero_m:CHAR_ART2[0],hero_f:CHAR_ART2[1]};
(function(){
 const B=CHAR_ART2,old=window.scSpeakerArt;if(typeof old!=='function')return;
 const img=u=>`<div class="sc-portrait sc-pixelportrait sc-art-portrait"><img src="${u}" alt=""></div>`;
 const pg=()=>{try{return S.meta&&S.meta.pg==='f'?'f':'m';}catch(e){return 'm';}};
 window.charHero=()=>pg()==='f'?B[1]:B[0];
 try{const P=SC_USER_ART.portraits;Object.defineProperty(P,'hero',{get:()=>window.charHero(),configurable:true});Object.defineProperty(P,'rival',{get:()=>B[7],configurable:true});}catch(e){}
 const L=a=>a.map(i=>B[i]);
 const CROWD=L([2,3,4,5,6,8,29,31,32,34,40,41,42,43]),GYM=L([9,10,12,14,15,16,17,25,26]),GRUNT=L([18,19,20,21,22]);
 const hs=s=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return h;};
 const pick=(a,w)=>a[hs(w)%a.length];
 window.scSpeakerArt=function(who){
  const w=String(who||'').trim();
  try{
   /* 외전〈작은 믿음, 거대한 승리〉 인물: 하나님은 그림 없이 말풍선만, 나머지는 어울리는 그림으로 고정해요 (번호 = 위 45장 순서) */
   if(w==='하나님'||w==='여호와')return '';
   /* 직접 그린 외전 인물 일러스트 (다윗·골리앗·사무엘·사울 왕·이새·엘리압) */
   const SIDE_ART={'다윗':"data:image/webp;base64,",'골리앗':"data:image/webp;base64,",'사무엘':"data:image/webp;base64,",'사울':"data:image/webp;base64,",'사울 왕':"data:image/webp;base64,",'사울왕':"data:image/webp;base64,",'이새':"data:image/webp;base64,",'엘리압':"data:image/webp;base64,"};
   if(SIDE_ART[w])return img(SIDE_ART[w]);
   const SIDE={'이스라엘 병사':42,'병사':42};
   if(SIDE[w]!=null)return img(B[SIDE[w]]);
   if(w==='주인공')return img(window.charHero());
   if(w==='이안')return img(B[7]);
   if(/^젊은 해준/.test(w))return img(B[33]);
   if(w==='해준'||/노인|할아버지|영감|어르신/.test(w))return img(B[27]);
   if(/할머니/.test(w))return img(B[28]);
   if(w==='서린')return img(B[30]);
   if(/^라온/.test(w))return img(B[45]);
   if(/연구소/.test(w))return img(B[32]);
   if(/마을 사람|주민|이웃|목동/.test(w))return img(B[29]);
   if(/우체부|집배원|배달/.test(w))return img(B[35]);
   if(/농부|어부|뱃사공|선장/.test(w))return img(B[39]);
   if(/상인|주인|가게/.test(w))return img(B[34]);
   if(/선생|교사|학자/.test(w))return img(B[44]);
   if(/간호사/.test(w))return img(B[37]);
   if(/조사단원/.test(w))return img(B[24]);
   if(/박사/.test(w))return img(B[36]);
   if(/도시 관장/.test(w))return img(B[13]);
   if(/관장|체육관/.test(w))return img(pick(GYM,w));
   if(/보스/.test(w))return img(B[23]);
   if(/조직|악당|단원/.test(w))return img(pick(GRUNT,w));
   if(/^패리퍼|구름이$/.test(w)){const id=(typeof MON!=='undefined'&&MON[279]&&MON[279].name==='패리퍼')?279:0;if(id)return `<div class="sc-portrait sc-pixelportrait scv-monportrait">${monImg(id,'front')}</div>`;}
   const a=old(who);
   if(/sc-art-portrait/.test(a)&&!/지라치/.test(w)&&!/monportrait/.test(a))return img(pick(CROWD,w));
   return a;
  }catch(e){return old(who);}
 };
})();
